{"source":"/*
 * A. Wizards and Demonstration
 * http://codeforces.com/problemset/problem/168/A
 * */
#include <stdio.h>
#include <math.h>

int main(int argc, char *argv[]) {
    int n, x, y;

    scanf("%d %d %d", &n, &x, &y);

    int need = (n * y + 99) / 100 - x;

    if (need < 0)
        printf("0\n");
    else
        printf("%d\n", need);
    return 0;
}
